<?php
/** Public and private shortcodes with semantic, keyboard-first output. */
defined( 'ABSPATH' ) || exit;
final class VWLB_Frontend {
	public function register(){add_shortcode('vwlb_wall',array($this,'wall'));add_shortcode('vwlb_video',array($this,'video'));add_shortcode('vwlb_live',array($this,'live'));add_shortcode('vwlb_channel',array($this,'channel'));add_shortcode('vwlb_studio_video',array($this,'studio_video'));add_shortcode('vwlb_studio_live',array($this,'studio_live'));add_shortcode('vwlb_history',array($this,'history'));}
	public function assets(){wp_register_style('vwlb',VWLB_URL.'assets/css/vwlb.css',array(),VWLB_VERSION);wp_register_script('vwlb',VWLB_URL.'assets/js/vwlb.js',array(),VWLB_VERSION,true);wp_localize_script('vwlb','VWLB',array('root'=>esc_url_raw(rest_url(VWLB_Contracts::API_NAMESPACE)),'nonce'=>wp_create_nonce('wp_rest'),'i18n'=>array('error'=>__('Something went wrong. Please retry.',VWLB_TEXT_DOMAIN),'saved'=>__('Saved.',VWLB_TEXT_DOMAIN))));}
	private function enqueue(){wp_enqueue_style('vwlb');wp_enqueue_script('vwlb');}
	public function wall($atts=array()){$this->enqueue();$data=VWLB_Repository::browse_videos(array('per_page'=>12));ob_start();?><main class="vwlb-shell" aria-labelledby="vwlb-wall-title"><header class="vwlb-hero"><h1 id="vwlb-wall-title"><?php esc_html_e('Video Wall',VWLB_TEXT_DOMAIN);?></h1><p><?php esc_html_e('Verified educational videos and live broadcasts.',VWLB_TEXT_DOMAIN);?></p></header><div class="vwlb-grid" role="list"><?php if(empty($data['items'])):?><section class="vwlb-empty" role="status"><h2><?php esc_html_e('No public videos yet',VWLB_TEXT_DOMAIN);?></h2><p><?php esc_html_e('Approved videos will appear here after review.',VWLB_TEXT_DOMAIN);?></p></section><?php else:foreach($data['items'] as $item):?><article class="vwlb-card" role="listitem"><a href="<?php echo esc_url($item['url']);?>"><div class="vwlb-thumb"><?php if($item['thumbnail_id']):echo wp_get_attachment_image($item['thumbnail_id'],'medium_large',false,array('loading'=>'lazy'));else:?><span aria-hidden="true">▶</span><?php endif;?></div><h2><?php echo esc_html($item['title']);?></h2><p><?php echo esc_html($item['excerpt']);?></p><span class="vwlb-meta"><?php echo esc_html(gmdate('H:i:s',(int)$item['duration_seconds']));?></span></a></article><?php endforeach;endif;?></div></main><?php return ob_get_clean();}
	public function video(){VWLB_Helpers::no_cache_private();$this->enqueue();$id=get_query_var('vwlb_video_id');if(!$id&&isset($_GET['video']))$id=sanitize_text_field(wp_unslash($_GET['video']));$payload=$id?VWLB_Videos::playback($id):null;if(is_wp_error($payload)||!$payload)return $this->state('restricted',__('Video unavailable',VWLB_TEXT_DOMAIN),__('The video is unavailable or you do not have access.',VWLB_TEXT_DOMAIN));$v=$payload['video'];$p=$payload['playback'];ob_start();?><main class="vwlb-shell vwlb-player-page" data-vwlb-video="<?php echo esc_attr($v['public_id']);?>"><nav class="vwlb-local-nav" aria-label="<?php esc_attr_e('Page navigation',VWLB_TEXT_DOMAIN);?>"><a href="javascript:history.back()"><?php esc_html_e('Back',VWLB_TEXT_DOMAIN);?></a><a href="<?php echo esc_url(home_url('/'));?>"><?php esc_html_e('Home',VWLB_TEXT_DOMAIN);?></a></nav><article><h1><?php echo esc_html($v['title']);?></h1><?php if('iframe'===$p['type']):?><div class="vwlb-player-frame"><iframe src="<?php echo esc_url($p['url']);?>" title="<?php echo esc_attr($v['title']);?>" loading="lazy" allow="autoplay; fullscreen; picture-in-picture" sandbox="<?php echo esc_attr($p['sandbox']);?>" allowfullscreen></iframe></div><?php else:?><video class="vwlb-player" controls playsinline preload="metadata" src="<?php echo esc_url($p['url']);?>" data-resume="<?php echo esc_attr($payload['session']['resume_seconds']??0);?>"><?php foreach($v['captions'] as $c):?><track kind="<?php echo esc_attr('captions'===$c['kind']?'captions':'subtitles');?>" srclang="<?php echo esc_attr($c['language']);?>" label="<?php echo esc_attr($c['language']);?>" src="<?php echo esc_url(rest_url(VWLB_Contracts::API_NAMESPACE.'/captions/'.$c['public_id']));?>"><?php endforeach;?><?php esc_html_e('Your browser does not support video playback.',VWLB_TEXT_DOMAIN);?></video><?php endif;?><div class="vwlb-actions" role="group" aria-label="<?php esc_attr_e('Video actions',VWLB_TEXT_DOMAIN);?>"><button type="button" data-vwlb-action="like" aria-pressed="false">👍 <?php esc_html_e('Like',VWLB_TEXT_DOMAIN);?></button><button type="button" data-vwlb-action="dislike" aria-pressed="false">👎 <?php esc_html_e('Dislike',VWLB_TEXT_DOMAIN);?></button><button type="button" data-vwlb-action="save" aria-pressed="false">🔖 <?php esc_html_e('Save',VWLB_TEXT_DOMAIN);?></button></div><div class="vwlb-status" role="status" aria-live="polite"></div><div class="vwlb-description"><?php echo wp_kses_post(wpautop($v['description']));?></div></article></main><?php return ob_get_clean();}
	public function live(){VWLB_Helpers::no_cache_private();$this->enqueue();$id=get_query_var('vwlb_live_id');if(!$id&&isset($_GET['live']))$id=sanitize_text_field(wp_unslash($_GET['live']));$event=$id?VWLB_Live::state($id):null;if(is_wp_error($event)||!$event)return $this->state('restricted',__('Live event unavailable',VWLB_TEXT_DOMAIN),__('The event is unavailable or restricted.',VWLB_TEXT_DOMAIN));ob_start();?><main class="vwlb-shell" data-vwlb-live="<?php echo esc_attr($event['public_id']);?>"><h1><?php echo esc_html($event['title']);?></h1><div class="vwlb-live-state" role="status" aria-live="polite"><strong><?php echo esc_html(ucwords(str_replace('_',' ',$event['status'])));?></strong><?php if('scheduled'===$event['status']):?><time datetime="<?php echo esc_attr($event['scheduled_start']);?>" data-vwlb-countdown><?php echo esc_html(get_date_from_gmt($event['scheduled_start'],get_option('date_format').' '.get_option('time_format')));?></time><?php endif;?></div><?php if(!empty($event['provider_degraded'])):?><div class="vwlb-warning" role="alert"><?php esc_html_e('The streaming provider is degraded. The page will retry safely.',VWLB_TEXT_DOMAIN);?></div><?php endif;?><?php if(!empty($event['playback']['url'])):?><div class="vwlb-player-frame"><iframe src="<?php echo esc_url($event['playback']['url']);?>" title="<?php echo esc_attr($event['title']);?>" allowfullscreen></iframe></div><?php endif;?><div><?php echo wp_kses_post(wpautop($event['description']));?></div></main><?php return ob_get_clean();}
	public function channel(){return $this->state('empty',__('Channel',VWLB_TEXT_DOMAIN),__('Channel videos and playlists appear here when public.',VWLB_TEXT_DOMAIN));}
	public function studio_video(){VWLB_Helpers::no_cache_private();if(!VWLB_Security::can(VWLB_Contracts::CAP_SUBMIT))return $this->state('restricted',__('Sign in required',VWLB_TEXT_DOMAIN),__('Only approved publishers can use Video Studio.',VWLB_TEXT_DOMAIN));$this->enqueue();return '<main class="vwlb-shell"><h1>'.esc_html__('Video Studio',VWLB_TEXT_DOMAIN).'</h1><div id="vwlb-studio-video" data-vwlb-studio="video"><p>'.esc_html__('Create, upload, process, caption, review and publish recorded video through File 10.',VWLB_TEXT_DOMAIN).'</p></div></main>';}
	public function studio_live(){VWLB_Helpers::no_cache_private();if(!VWLB_Security::can(VWLB_Contracts::CAP_BROADCAST))return $this->state('restricted',__('Access restricted',VWLB_TEXT_DOMAIN),__('Live Studio requires broadcaster authorization.',VWLB_TEXT_DOMAIN));$this->enqueue();return '<main class="vwlb-shell"><h1>'.esc_html__('Live Studio',VWLB_TEXT_DOMAIN).'</h1><div id="vwlb-studio-live" data-vwlb-studio="live"><p>'.esc_html__('Schedule, rehearse, issue a one-time stream key, moderate, end and publish replay.',VWLB_TEXT_DOMAIN).'</p></div></main>';}
	public function history(){VWLB_Helpers::no_cache_private();if(!is_user_logged_in())return $this->state('restricted',__('Sign in required',VWLB_TEXT_DOMAIN),__('Sign in to view private watch history.',VWLB_TEXT_DOMAIN));global $wpdb;$rows=$wpdb->get_results($wpdb->prepare('SELECT s.progress_seconds,s.completed,s.updated_at,v.public_id,v.slug,v.title FROM '.VWLB_Helpers::table('playback_sessions').' s JOIN '.VWLB_Helpers::table('videos').' v ON v.id=s.object_id WHERE s.user_id=%d AND s.object_type=%s ORDER BY s.updated_at DESC LIMIT 100',get_current_user_id(),'video'),ARRAY_A);ob_start();?><main class="vwlb-shell"><h1><?php esc_html_e('Video History',VWLB_TEXT_DOMAIN);?></h1><?php if(!$rows):echo $this->state('empty',__('No history yet',VWLB_TEXT_DOMAIN),__('Videos you watch while signed in will appear here.',VWLB_TEXT_DOMAIN));else:?><ol class="vwlb-history"><?php foreach($rows as $r):?><li><a href="<?php echo esc_url(home_url('/video/'.$r['public_id'].'/'.$r['slug'].'/'));?>"><?php echo esc_html($r['title']);?></a> <span><?php echo esc_html(gmdate('H:i:s',(int)$r['progress_seconds']));?></span></li><?php endforeach;?></ol><?php endif;?></main><?php return ob_get_clean();}
	private function state($class,$title,$message){return '<section class="vwlb-state vwlb-state-'.esc_attr($class).'" role="status"><h2>'.esc_html($title).'</h2><p>'.esc_html($message).'</p><p><a href="'.esc_url(home_url('/')).'">'.esc_html__('Home',VWLB_TEXT_DOMAIN).'</a></p></section>';}
}
